test('HTTP a blocked request with one successful form reports that exact receipt and the unfinished remainder',async()=>{
  const reviews=[],responseGuard=new CrmResponseGuard({runtimeFactory:options=>controlledSession({...options,fauxResponses:[context=>{const input=JSON.parse(context.messages.find(m=>m.role==='user').content.find(p=>p.type==='text').text);reviews.push(input);const bad=input.context.kind==='host_outcome'&&input.review_target.explanation_texts.includes('Everything succeeded and no further action is needed.');return call('review_message',{approved:!bad,issues:bad?['The asset query failed, so the explanation cannot claim everything succeeded.']:[]});}]})}),f=await fixture({responseGuard});try{const user=await f.newConversation();ensureCrm(f.app.store.get(user.id)).faults={crm_get_assets:{code:'SERVICE_UNAVAILABLE',status:503}};let state=await user.chat(complaintMessage+' After recording the complaint, show the municipal asset categories.',[plan([step('write','crm_create_form_request'),step('assets','crm_get_assets',['write'])]),call('crm_create_form_request',{step_id:'write',body:complaint()})]);assert.equal(state.status,'confirmation');f.turns.push([call('execute_confirmed_submission',{step_id:'write'}),call('crm_get_assets',{step_id:'assets'}),finish('Everything succeeded and no further action is needed.',{state:'blocked'}),repairFinish('',{state:'blocked'})]);await user.post('/api/approve-operation',{proposal_id:state.pendingOperation.id});state=await user.settled();const answer=state.messages.at(-1),number=state.receipts[0].result.data.result.id;assert.equal(state.status,'blocked');assert.equal(answer.presentation_source,'host_submission');assert.ok(answer.text.includes(number));assert.match(answer.text,/partial|not complete(?:d)?|could not complete|incomplete|not finished|unfinished/iu);assert.ok(!answer.text.includes('Everything succeeded'));assert.equal(state.receipts.length,1);assert.deepEqual(apiCalls(state).map(x=>x.operation),['crm_create_form_request','crm_get_assets']);assert.equal(state.events.filter(x=>x.type==='confirmation_required').length,1);assert.doesNotMatch(answer.text,/requested operation is not connected|permanently|SERVICE_UNAVAILABLE|crm_get_assets/iu);assert.match(answer.text,/do not.*(?:re.?submit|submit.*again)|no need.*(?:re.?submit|submit.*again)|not.*repeat.*submi/iu);const outcomes=reviews.filter(r=>r.context.kind==='host_outcome');assert.equal(outcomes.length,3);assert.deepEqual(outcomes.slice(-2).map(r=>r.review_scope),['explanation_facts','outcome_applicability_language']);assert.ok(outcomes.slice(-2).every(r=>r.review_target.host_text===answer.text&&r.review_target.explanation_texts.length===0),'Both reviewers must see the actual partial-success public result');assert.ok(outcomes.every(r=>JSON.stringify(r.context.read_failures)==JSON.stringify([{operation:'crm_get_assets',error_code:'SERVICE_UNAVAILABLE'}])),'A real current-plan failed read is control evidence, never a fabricated successful receipt');
  }finally{await f.app.close();}
});

