test('HTTP delivered description quotations allow exact formatting or explicit multi-quote joining and control metadata never reaches CRM',async()=>{
  for(const multi of[false,true]){const f=await fixture();try{const user=await f.newConversation(),first='The counter was closed.',second='No queue information was visible.',description=multi?first+'\n'+second:'  THE COUNTER\n WAS CLOSED. ',body={...complaint(),subject:'Counter service',Description:description},canonical=structuredClone(BY_ID.get('crm_create_form_request').input);let state=await user.chat(first+' '+(multi?second+' ':'')+'Please prepare a local public complaint with title Counter service. My name is Lina Citizen, email lina@example.test, phone 0501234567. I have no attachments.',[plan([step('write','crm_create_form_request')]),call('crm_create_form_request',{step_id:'write',body,...(multi?{description_source:{quotes:[first,second]}}:{})})]);assert.equal(state.status,'confirmation');assert.deepEqual(state.pendingOperation.parameters,{body});assert.equal(apiCalls(state).length,0);const proposal=state.pendingOperation.id;f.turns.push([call('execute_confirmed_submission',{step_id:'write'}),finish()]);assert.equal((await user.post('/api/approve-operation',{proposal_id:proposal})).status,202);state=await user.settled();assert.equal(state.status,'completed');assert.deepEqual(state.receipts[0].parameters,{body});assert.equal(state.receipts[0].parameters.description_source,undefined);assert.equal(apiCalls(state).length,1);assert.equal(state.events.filter(e=>e.type==='confirmation_required').length,1,'Cached validated source must survive the exact approved continuation without another confirmation');assert.equal((await user.post('/api/approve-operation',{proposal_id:proposal})).status,409);assert.deepEqual(BY_ID.get('crm_create_form_request').input,canonical);assert.equal(canonical.properties.description_source,undefined,'Description-source control is local policy, not a guide wire parameter');
  }finally{await f.app.close();}}
});

