  const f=await fixture();try{const user=await f.newConversation(),body={...complaint(),subject:'Counter service',Description:'The counter was closed.'};let state=await user.chat('The counter was closed. Prepare a local complaint titled Counter service. My name is Lina Citizen, email lina@example.test, phone 0501234567. No attachments.',[plan([step('write','crm_create_form_request')]),call('crm_create_form_request',{step_id:'write',body})]);assert.equal(state.status,'confirmation');const session=f.app.store.get(user.id);session.pendingOperation.parameters.body.Description='The counter was closed during three separate visits.';session.plans.find(p=>p.id===session.activePlanId).steps.find(s=>s.id==='write').parameters=structuredClone(session.pendingOperation.parameters);await f.app.store.save(session);state=await user.get();const proposal=state.pendingOperation.id,edited=structuredClone(state.pendingOperation.parameters);edited.body.subject='New title only';const result=await user.post('/api/edit-operation',{proposal_id:proposal,value:{parameters:edited}});assert.equal(result.status,400);assert.equal(result.body.error.code,'DESCRIPTION_SOURCE_REQUIRED');state=await user.get();assert.equal(apiCalls(state).length,0);assert.equal(state.events.filter(e=>e.type==='confirmation_required').length,1,'A title-only change must not produce a new card for an unsupported restored description');
  }finally{await f.app.close();}
