test('HTTP public action plans review actual intent and dependencies while host Arabic labels prevent free future prose from causing retry loops',async()=>{
  const reviews=[],responseGuard=new CrmResponseGuard({runtimeFactory:options=>controlledSession({...options,fauxResponses:[context=>{const input=JSON.parse(context.messages.find(m=>m.role==='user').content.find(p=>p.type==='text').text);reviews.push(input);const unsupportedPlanProse=['plan','plan_selection'].includes(input.context.kind)&&input.review_target.kind!=='action_plan';return call('review_message',{approved:!unsupportedPlanProse,issues:unsupportedPlanProse?['This prose-only future plan has no structured action intent to verify.']:[]});}]})});const f=await fixture({responseGuard});try{const user=await f.newConversation();await user.login('demo');const proposed=()=>call('propose_plan',{goal:'UNREVIEWED-FUTURE-PROSE crm_get_incidents',summary:'UNREVIEWED-FUTURE-PROSE before any returned evidence',steps:[{id:'history',title:'UNREVIEWED-FUTURE-PROSE crm_get_incidents',capability:'crm_get_incidents',depends_on:[]},{id:'reply',title:'UNREVIEWED-FUTURE-PROSE explain later',capability:'respond',depends_on:['history']}]});const state=await user.chat('أريد الاطلاع على بلاغاتي السابقة فقط.',[proposed(),call('crm_get_incidents',{step_id:'history'}),finish()]);assert.equal(state.status,'completed');assert.deepEqual(apiCalls(state).map(c=>c.operation),['crm_get_incidents']);assert.equal(state.plans.length,1);assert.equal(state.events.filter(e=>e.type==='confirmation_required').length,0);const plans=reviews.filter(r=>r.context.kind==='plan_selection');assert.equal(plans.length,2);assert.ok(plans.every(r=>r.review_target.kind==='action_plan'));assert.ok(plans.every(r=>JSON.stringify(r.review_target).includes('crm_get_incidents')));assert.ok(plans.every(r=>JSON.stringify(r.review_target).includes('history')));assert.ok(plans.every(r=>!JSON.stringify(r.review_target).includes('UNREVIEWED-FUTURE-PROSE')));const visible=state.plans.flatMap(p=>[p.goal,p.summary,...p.steps.map(s=>s.title)]).join('\n');assert.match(visible,/\p{Script=Arabic}/u);assert.doesNotMatch(visible,/UNREVIEWED-FUTURE-PROSE|crm_get_incidents/u);assert.ok(state.events.some(e=>e.type==='tool_start'&&e.name==='propose_plan'&&e.arguments.goal.includes('UNREVIEWED-FUTURE-PROSE')),'The unmodified author arguments remain observable as trace evidence');
  }finally{await f.app.close();}
});

