test('HTTP a post-write reviewer outage preserves the actual same-origin receipt after replanning and never presents it as a new submission for another origin',async()=>{
  const reviews=[],responseGuard=new CrmResponseGuard({runtimeFactory:options=>controlledSession({...options,fauxResponses:[context=>{
    const input=JSON.parse(context.messages.find(m=>m.role==='user').content.find(p=>p.type==='text').text);reviews.push(input);
    if(['host_outcome','outcome_presentation'].includes(input.context.kind))throw Error('Injected final reviewer transport outage');
    return call('review_message',{approved:true,issues:[]});
  }]})});
  const f=await fixture({responseGuard});try{const user=await f.newConversation();let state=await user.chat(complaintMessage,[plan([step('write','crm_create_form_request')]),call('crm_create_form_request',{step_id:'write',body:complaint()})]);assert.equal(state.status,'confirmation');const approved=state.pendingOperation.id,writePlan=state.activePlanId;let duplicateAttemptConsumed=false;
    f.turns.push([call('execute_confirmed_submission',{step_id:'write'}),plan([]),finish(),()=>{duplicateAttemptConsumed=true;return call('execute_confirmed_submission',{step_id:'write'});}]);assert.equal((await user.post('/api/approve-operation',{proposal_id:approved})).status,202);state=await user.settled();assert.equal(state.status,'failed');assert.equal(duplicateAttemptConsumed,false);assert.notEqual(state.activePlanId,writePlan,'The success acknowledgement must survive replacement of the original write plan');const receipt=state.receipts[0],number=receipt.result.data.result.id,answer=state.messages.at(-1);assert.equal(state.receipts.length,1);assert.deepEqual(apiCalls(state).map(c=>c.operation),['crm_create_form_request']);assert.deepEqual(receipt.parameters,{body:complaint()});assert.deepEqual(answer.receipt_ids,[receipt.id]);assert.ok(answer.text.includes(number));assert.ok(answer.text.includes(complaint().subject));assert.match(answer.text,/local|simulat/iu);assert.match(answer.text,/verification|stopped/iu);assert.doesNotMatch(answer.text,/Injected final|RESPONSE_GUARD_UNAVAILABLE/u);assert.equal(state.events.filter(e=>e.type==='confirmation_required').length,1);assert.equal(state.pendingOperation,null);assert.equal(state.events.filter(e=>e.type==='tool_end'&&e.name==='finish'&&e.result?.error==='RESPONSE_GUARD_UNAVAILABLE').length,1);assert.equal((await user.post('/api/approve-operation',{proposal_id:approved})).status,409);
    const firstOrigin=f.app.store.get(user.id).plans.find(p=>p.id===writePlan).origin_message_id;state=await user.chat('Explain the supported services. Do not submit or retry any complaint.',[plan([]),call('finish',{state:'answered',message:'This assistant can read connected records and prepare local complaints for your separate review.',receipt_ids:[]})]);assert.equal(state.status,'failed');const nextOrigin=f.app.store.get(user.id).plans.find(p=>p.id===state.activePlanId).origin_message_id;assert.notEqual(nextOrigin,firstOrigin);assert.deepEqual(state.messages.at(-1).receipt_ids,[]);assert.ok(!state.messages.at(-1).text.includes(number),'An old successful write must not be re-announced as a new completion in a different user request');assert.equal(state.receipts.length,1);assert.equal(apiCalls(state).length,1);assert.equal(state.events.filter(e=>e.type==='confirmation_required').length,1);const finalReviews=reviews.filter(r=>['host_outcome','outcome_presentation'].includes(r.context.kind));assert.equal(finalReviews.length,2,'Each outage terminates immediately, without a second verifier or author retry');assert.equal(finalReviews[0].review_scope,'explanation_facts');assert.equal(finalReviews[1].review_scope,'facts');
  }finally{await f.app.close();}
});

