  for(const kind of['submission_draft','missing_information']){const reviews=[],responseGuard=new CrmResponseGuard({runtimeFactory:options=>controlledSession({...options,fauxResponses:[context=>{const input=JSON.parse(context.messages.find(m=>m.role==='user').content.find(p=>p.type==='text').text);reviews.push(input);return call('review_message',{approved:input.context.kind!==kind,issues:input.context.kind===kind?['The verifier cannot establish that this proposed customer-facing content preserves the delivered request.']:[]});}]})}),f=await fixture({responseGuard});try{const user=await f.newConversation(),body=complaint();delete body.CustomerInformation.EmailAddress;const attempt=()=>kind==='submission_draft'?call('crm_create_form_request',{step_id:'write',body:complaint()}):call('request_input',{step_id:'email',kind:'text',operation:'crm_create_form_request',fields:['body.CustomerInformation.EmailAddress'],known_parameters:{body},question:'Which email address should be recorded in the local complaint?'});let fourth=false;const state=await user.chat(kind==='submission_draft'?complaintMessage:'The shared waste container has not been emptied. Please prepare the local complaint with title Waste collection. My name is Lina Citizen, phone 0501234567, no attachments; I have not yet provided an email address.',[plan(kind==='submission_draft'?[step('write','crm_create_form_request')]:[step('email','input'),step('write','crm_create_form_request',['email'])]),attempt(),attempt(),attempt(),()=>{fourth=true;return attempt();}]);assert.equal(state.status,'failed');assert.equal(fourth,false);assert.equal(state.messages.at(-1).error_code,'RESPONSE_REVIEW_FAILED');assert.equal(reviews.filter(r=>r.context.kind===kind).length,3);assert.equal(state.pendingInput,null);assert.equal(state.pendingOperation,null);assert.equal(state.receipts.length,0);assert.equal(apiCalls(state).length,0);assert.equal(state.events.filter(e=>e.type==='confirmation_required'||e.type==='input_required').length,0);
  }finally{await f.app.close();}}
