test('HTTP a receipt-free answer cannot omit its explanation and still passes the strict two ordinary prose gates after repair',async()=>{
  const reviews=[],responseGuard=new CrmResponseGuard({runtimeFactory:options=>controlledSession({...options,fauxResponses:[context=>{reviews.push(JSON.parse(context.messages.find(m=>m.role==='user').content.find(p=>p.type==='text').text));return call('review_message',{approved:true,issues:[]});}]})}),f=await fixture({responseGuard});try{const user=await f.newConversation(),safe='This assistant can read connected records and prepare local drafts for separate review. No request was submitted.';const state=await user.chat('Explain what the assistant can do; do not submit anything.',[plan([]),call('finish',{state:'answered',receipt_ids:[]}),context=>{assert.equal(observations(context).at(-1).error,'EXPLANATION_REQUIRED');assert.equal(f.app.store.get(user.id).messages.filter(m=>m.kind==='result').length,0);return call('finish',{state:'answered',message:safe,receipt_ids:[]});}]);assert.equal(state.status,'completed');assert.equal(state.messages.at(-1).text,safe);assert.equal(state.messages.at(-1).presentation_source,'verified_model');const prose=reviews.filter(r=>r.context.kind==='outcome_presentation');assert.deepEqual(prose.map(r=>r.review_scope),['facts','capability_language']);assert.ok(prose.every(r=>r.review_target.kind==='prose'&&r.review_target.texts[0]===safe));assert.ok(!reviews.some(r=>r.context.kind==='host_outcome'));assert.equal(state.receipts.length,0);assert.equal(apiCalls(state).length,0);assert.equal(state.pendingOperation,null);
  }finally{await f.app.close();}
});

test('HTTP a fabricated or earlier-request action quote cannot attach an unavailable-operation label to a new history query',async()=>{
  const reviews=[],responseGuard=new CrmResponseGuard({runtimeFactory:options=>controlledSession({...options,fauxResponses:[context=>{reviews.push(JSON.parse(context.messages.find(m=>m.role==='user').content.find(p=>p.type==='text').text));return call('review_message',{approved:true,issues:[]});}]})}),f=await fixture({responseGuard});try{const user=await f.newConversation();await user.login('demo');await user.chat('Please explain whether a duplicate fee can be refunded here.',[plan([]),call('finish',{state:'answered',message:'A refund cannot be performed through this assistant. No refund was made.',receipt_ids:[]})]);const before=reviews.length;const state=await user.chat('Show the reports visible to my signed-in account.',[plan([step('history','crm_get_incidents')]),call('crm_get_incidents',{step_id:'history'}),finish('An unrelated service is unavailable.',{case_guidance:['action_unavailable'],unavailable_action_quote:'Send an inspector tomorrow'}),context=>{assert.equal(observations(context).at(-1).error,'UNAVAILABLE_ACTION_SOURCE_REQUIRED');return finish('A refund is unavailable.',{case_guidance:['action_unavailable'],unavailable_action_quote:'whether a duplicate fee can be refunded here'})(context);},context=>{assert.equal(observations(context).at(-1).error,'UNAVAILABLE_ACTION_SOURCE_REQUIRED');return finish('')(context);}]);assert.equal(state.status,'completed');assert.equal(state.messages.at(-1).presentation_source,'host_case');assert.ok(!state.messages.at(-1).case_guidance?.includes('action_unavailable'));assert.ok(!reviews.slice(before).some(r=>r.context.kind==='unavailable_intent'),'Unrelated old or invented text must fail the host source check before any semantic reviewer');assert.equal(state.events.filter(e=>e.type==='tool_end'&&e.result?.error==='UNAVAILABLE_ACTION_SOURCE_REQUIRED').length,2);assert.deepEqual(apiCalls(state).map(c=>c.operation),['crm_get_incidents']);assert.equal(state.receipts.length,1);assert.equal(state.pendingOperation,null);assert.equal(state.events.filter(e=>e.type==='confirmation_required').length,0);
  }finally{await f.app.close();}
});
